def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts: dict[str, list] = {}  # name -> [balance, frozen]
    history: list[list[tuple]] = []  # inverse actions of successful, unreverted non-undo ops
    rejected: list[int] = []

    def valid_amount(tok: str) -> bool:
        return len(tok) > 0 and all("0" <= c <= "9" for c in tok)

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0]
        n = len(parts)
        ok = False
        undo_actions = None

        if verb == "undo" and n == 1:
            if history:
                for action in history.pop():
                    if action[0] == "del":
                        del accounts[action[1]]
                    elif action[0] == "bal":
                        accounts[action[1]][0] += action[2]
                    elif action[0] == "frz":
                        accounts[action[1]][1] = action[2]
                ok = True

        elif verb == "open" and n == 3 and valid_amount(parts[2]) and parts[1] not in accounts:
            name, amt = parts[1], int(parts[2])
            accounts[name] = [amt, False]
            undo_actions = [("del", name)]
            ok = True

        elif verb == "deposit" and n == 3 and valid_amount(parts[2]):
            name, amt = parts[1], int(parts[2])
            if amt > 0 and name in accounts:
                accounts[name][0] += amt
                undo_actions = [("bal", name, -amt)]
                ok = True

        elif verb == "withdraw" and n == 3 and valid_amount(parts[2]):
            name, amt = parts[1], int(parts[2])
            if amt > 0 and name in accounts and not accounts[name][1] and accounts[name][0] >= amt:
                accounts[name][0] -= amt
                undo_actions = [("bal", name, amt)]
                ok = True

        elif verb == "transfer" and n == 4 and valid_amount(parts[3]):
            src, dst, amt = parts[1], parts[2], int(parts[3])
            if (amt > 0 and src != dst and src in accounts and dst in accounts
                    and not accounts[src][1] and accounts[src][0] >= amt):
                accounts[src][0] -= amt
                accounts[dst][0] += amt
                undo_actions = [("bal", src, amt), ("bal", dst, -amt)]
                ok = True

        elif verb == "freeze" and n == 2:
            name = parts[1]
            if name in accounts and not accounts[name][1]:
                accounts[name][1] = True
                undo_actions = [("frz", name, False)]
                ok = True

        elif verb == "unfreeze" and n == 2:
            name = parts[1]
            if name in accounts and accounts[name][1]:
                accounts[name][1] = False
                undo_actions = [("frz", name, True)]
                ok = True

        if ok:
            if undo_actions is not None:
                history.append(undo_actions)
        else:
            rejected.append(i)

    balances = {name: acct[0] for name, acct in accounts.items()}
    return balances, rejected
